
(()=>{'use strict';const el=id=>document.getElementById(id);
// The obsolete document screen stays inert for legacy references; first-page links own entry.
const splash=el('tpuApprovedSplash'),official=el('tpuOfficialDocs');
if(official){official.hidden=true;new MutationObserver(()=>{if(!official.hidden){official.hidden=true;if(splash)splash.hidden=false;}}).observe(official,{attributes:true,attributeFilter:['hidden']});}
const director=el('ntDirector'),panel=el('ntPanel');
function gate(){if(!director||!splash)return;director.classList.toggle('natura-entry-hidden',!splash.hidden);if(!splash.hidden)window.WOWNatuTeraDirector?.close();}
if(splash)new MutationObserver(gate).observe(splash,{attributes:true,attributeFilter:['hidden']});gate();
const tera=el('wowQuietTera');if(tera){tera.title='Тера — представителният филм';tera.setAttribute('aria-label','Тера — отвори представителния филм');}
if(!panel)return;
const art=panel.querySelector('.natu-tree-art');if(art){art.innerHTML='';const img=document.createElement('img');img.src='data:image/png;base64,';img.alt='';img.draggable=false;art.append(img);}
const captions={photos:'Снимки на зоната',zoneDocs:'Документи на зоната',welcome:'Нату и Тера',finish:'Край',tera:'Филмът на Тера',presentation:'Представяне',intro:'Натко',home:'Начало WOW',classic:'Документи ТПУ',forward:'Напред',archive:'Фотоархив'};
for(const b of panel.querySelectorAll('[data-quiet-action]')){const short=captions[b.dataset.quietAction];if(short){b.title=b.textContent;b.textContent=short;}}
// Soft leaf accents animate independently, without moving hit areas or conversation.
const leaves=document.createElement('div');leaves.className='natura-living-leaves';leaves.setAttribute('aria-hidden','true');for(let i=0;i<7;i++){const leaf=document.createElement('i');leaf.style.setProperty('--leaf-i',i);leaves.append(leaf);}panel.append(leaves);
})();

